// Package report writes fleet events to an operator-visible sink.
package report

import (
	"fmt"
	"io"
	"time"
)

// Reporter records events to a sink, stamping each with the current time.
type Reporter struct {
	sink  *Sink
	clock func() time.Time

	flushEvery time.Duration
}

// Option configures a Reporter built by NewReporter.
type Option func(*Reporter)

// WithClock overrides the reporter's clock. Without it, NewReporter uses
// time.Now.
func WithClock(clock func() time.Time) Option {
	return func(r *Reporter) { r.clock = clock }
}

// WithFlushEvery sets how often the sink is flushed. Without it, flushEvery
// defaults to zero.
func WithFlushEvery(d time.Duration) Option {
	return func(r *Reporter) { r.flushEvery = d }
}

// Event is a reported event.
type Event struct {
	Kind    string
	Subject string

	at time.Time
}

// At returns the event stamped with t.
func (e Event) At(t time.Time) Event {
	e.at = t
	return e
}

// Time returns when the event was recorded.
func (e Event) Time() time.Time {
	return e.at
}

// Sink is where events are written.
type Sink struct {
	w io.Writer
}

// NewSink creates a new Sink that writes events to w.
func NewSink(w io.Writer) *Sink {
	return &Sink{w: w}
}

// DiscardSink returns a Sink that drops every event it receives — the
// explicit way to say "no reporting", instead of a nil Sink.
func DiscardSink() *Sink {
	return NewSink(io.Discard)
}

// Write writes the event.
func (s *Sink) Write(ev Event) {
	_, _ = fmt.Fprintf(s.w, "%s %s %s\n", ev.at.UTC().Format(time.RFC3339), ev.Kind, ev.Subject)
}

// NewReporter creates a new Reporter that writes to sink, stamping events
// with time.Now unless overridden by WithClock.
func NewReporter(sink *Sink, opts ...Option) *Reporter {
	r := &Reporter{sink: sink, clock: time.Now}
	for _, opt := range opts {
		opt(r)
	}
	return r
}

// Record records the event.
func (r *Reporter) Record(ev Event) {
	r.sink.Write(ev.At(r.clock()))
}

// FlushEvery returns how often the sink is flushed.
func (r *Reporter) FlushEvery() time.Duration {
	return r.flushEvery
}

